108→<script>
109→(function () {
110→  // Wait for app embed to set window.__zccAppEnabled.
111→  // App embed (target: body) may load after this section block, so we poll briefly.
112→  var maxWait = 3000; // ms
113→  var interval = 50;  // ms
114→  var elapsed = 0;
115→
116→  function tryInit() {
117→    if (window.__zccAppEnabled) {
118→      init();
119→    } else if (elapsed < maxWait) {
120→      elapsed += interval;
121→      setTimeout(tryInit, interval);
122→    }
123→    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
124→  }
125→
126→  // Start checking — if already set, runs immediately
127→  if (document.readyState === 'loading') {
128→    document.addEventListener('DOMContentLoaded', tryInit);
129→  } else {
130→    tryInit();
131→  }
132→
133→  function init() {
134→  var ROOT_ID = "zcc-widget-{{ block.id }}";
135→  var container = document.getElementById(ROOT_ID);
136→  if (!container) return;
137→
138→  var SHOP = container.dataset.shop;
139→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
140→
141→  // Try embedded config from metafield first (instant, no network needed)
142→  var configStr = container.getAttribute("data-config");
143→  if (configStr) {
144→    try {
145→      renderWidget(JSON.parse(configStr));
146→      return;
147→    } catch (e) {
148→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
149→    }
150→  }
151→
152→  // Fallback: fetch config from API
153→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
154→    .then(function (r) {
155→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
156→      return r.json();
157→    })
158→    .then(function (cfg) { renderWidget(cfg); })
159→    .catch(function (err) {
160→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
161→      renderWidget({});
162→    });
163→
164→  function renderWidget(cfg) {
165→    // Merge with defaults
166→    var D = {
167→      position: "inline",
168→      heading: "Check Delivery Availability",
169→      placeholder: "Enter your zip code",
170→      buttonText: "Check",
171→      successMessage: "Great news! We deliver to your area.",
172→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
173→      notFoundMessage: "We currently do not ship to this ZIP code.",
174→      primaryColor: "#008060",
175→      successColor: "#008060",
176→      errorColor: "#D72C0D",
177→      backgroundColor: "#FFFFFF",
178→      textColor: "#202223",
179→      borderRadius: "8",
180→      showEta: true,
181→      showZone: false,
182→      showWaitlistOnFailure: false,
183→      showCod: true,
184→      showReturnPolicy: true,
185→      showCutoffTime: true,
186→      showDeliveryDays: true,
187→      customCss: "",
188→      blockCartOnInvalid: false,
189→      showSocialProof: true,
190→      widgetStyle: "minimal",
191→    };
192→    Object.keys(D).forEach(function (k) {
193→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
194→    });
195→
196→    var rad = cfg.borderRadius + "px";
197→    var WID = "zcc-" + ROOT_ID;
198→
199→    if (cfg.position === "floating") {
200→      renderFloating(cfg, WID, rad);
201→    } else if (cfg.position === "popup") {
202→      renderPopup(cfg, WID, rad);
203→    } else {
204→      renderInline(cfg, WID, rad);
205→    }
206→
207→    // If blockCartOnInvalid is enabled, disable ATC/Buy Now buttons on page load
208→    // until the customer validates their ZIP code
209→    if (cfg.blockCartOnInvalid) {
210→      blockCartButtonsInitial();
211→    }
212→  }
213→
214→  // ── Block ATC buttons on page load (before any ZIP check) ─────────────────
215→  function blockCartButtonsInitial() {
216→    var ATC_SELECTORS = [
217→      'button[name="add"]',
218→      '.product-form__submit',
219→      '[data-product-add]',
220→      '.btn--add-to-cart',
221→      '.product-form button[type="submit"]',
222→      'button.shopify-payment-button__button',
223→      '.shopify-payment-button button',
224→      'button.product-form__cart-submit'
225→    ].join(',');
226→
227→    function doBlock() {
228→      try {
229→        var atcBtns = document.querySelectorAll(ATC_SELECTORS);
230→        atcBtns.forEach(function(b) {
231→          if (!b.closest('[data-zcc-widget]')) {
232→            if (!b.getAttribute('data-zcc-blocked')) {
233→              b.setAttribute('data-zcc-orig-title', b.title || '');
234→            }
235→            b.disabled = true;
236→            b.style.opacity = '0.5';
237→            b.title = 'Please check ZIP code availability first';
238→            b.setAttribute('data-zcc-blocked', 'true');
239→          }
240→        });
241→      } catch(e) {}
242→    }
243→
244→    // Block immediately + delays for dynamic buttons (Shopify Buy Now renders late)
245→    doBlock();
246→    setTimeout(doBlock, 500);
247→    setTimeout(doBlock, 1500);
248→
249→    // MutationObserver for dynamic payment buttons
250→    if (typeof MutationObserver !== 'undefined') {

250→    if (typeof MutationObserver !== 'undefined') {
251→      var observer = new MutationObserver(function() { doBlock(); });
252→      var form = document.querySelector('.product-form, [data-product-form], form[action*="/cart/add"]');
253→      if (form) {
254→        observer.observe(form, { childList: true, subtree: true });
255→        setTimeout(function() { observer.disconnect(); }, 10000);
256→      }
257→    }
258→  }
259→
260→  // ── Scope custom CSS: auto-prefix selectors with widget container ID ──────
261→  function scopeCustomCss(rawCss, wid) {
262→    if (!rawCss) return "";
263→    // Strip </style> tags to prevent injection
264→    var css = rawCss.replace(/<\/style>/gi, "");
265→    var result = "";
266→    var i = 0;
267→    while (i < css.length) {
268→      // Skip whitespace
269→      while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
270→      if (i >= css.length) break;
271→      // Pass through @keyframes and @font-face unchanged
272→      if (css[i] === '@') {
273→        var atRule = "";
274→        var j = i;
275→        while (j < css.length && css[j] !== '{' && css[j] !== ';') { atRule += css[j]; j++; }
276→        var atName = atRule.trim().toLowerCase();
277→        if (atName.indexOf("@keyframes") === 0 || atName.indexOf("@font-face") === 0) {
278→          result += atRule;
279→          if (j < css.length && css[j] === '{') {
280→            var depth = 1; result += css[j]; j++;
281→            while (j < css.length && depth > 0) {
282→              if (css[j] === '{') depth++;
283→              if (css[j] === '}') depth--;
284→              result += css[j]; j++;
285→            }
286→          }
287→          i = j; continue;
288→        }
289→        // @media: scope inner rules
290→        if (atName.indexOf("@media") === 0) {
291→          result += atRule;
292→          if (j < css.length && css[j] === '{') {
293→            result += '{'; j++;
294→            // Collect inner content
295→            var depth = 1; var inner = "";
296→            while (j < css.length && depth > 0) {
297→              if (css[j] === '{') depth++;
298→              if (css[j] === '}') depth--;
299→              if (depth > 0) inner += css[j];
300→              j++;
301→            }
302→            result += scopeCustomCss(inner, wid);
303→            result += '}';
304→          }
305→          i = j; continue;
306→        }
307→      }
308→      // Regular rule: grab selector, prefix with #wid
309→      var sel = ""; var body = "";
310→      while (i < css.length && css[i] !== '{') { sel += css[i]; i++; }
311→      if (i < css.length) { i++; } // skip {
312→      var depth = 1;
313→      while (i < css.length && depth > 0) {
314→        if (css[i] === '{') depth++;
315→        if (css[i] === '}') depth--;
316→        if (depth > 0) body += css[i];
317→        i++;
318→      }
319→      if (sel.trim()) {
320→        // Split multiple selectors by comma and prefix each
321→        var selectors = sel.split(',').map(function(s) {
322→          s = s.trim();
323→          if (!s) return '';
324→          return '#' + wid + ' ' + s;
325→        }).filter(Boolean).join(', ');
326→        result += selectors + ' {' + body + '}';
327→      }
328→    }
329→    return result;
330→  }
331→
332→  // ── Shared meta/waitlist CSS — injected by all three style presets ──────────
333→  function buildSharedCss(W, cfg) {
334→    return (
335→      W + " .zcc-row{display:flex !important;gap:0 !important;margin-bottom:0 !important}" +
336→      W + " .zcc-result-icon{flex-shrink:0 !important;width:24px !important;height:24px !important;display:flex !important;align-items:center !important;justify-content:center !important}" +
337→      W + " .zcc-result-icon svg{width:22px !important;height:22px !important}" +
338→      W + " .zcc-result-content{flex:1 !important;min-width:0 !important}" +
339→      W + " .zcc-meta{margin-top:6px !important;font-size:13px !important;opacity:.85 !important;display:flex !important;align-items:center !important;gap:6px !important}" +
340→      W + " .zcc-meta svg{width:14px !important;height:14px !important;flex-shrink:0 !important}" +
341→      W + " .zcc-cutoff{margin-top:6px !important;font-size:0.85em !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:6px !important}" +
342→      W + " .zcc-days{margin-top:6px !important;font-size:0.85em !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:6px !important}" +
343→      W + " .zcc-cod{margin-top:6px !important;font-size:0.85em !important;font-weight:500 !important;display:flex !important;align-items:center !important;gap:6px !important}" +
344→      W + " .zcc-cod--available{color:#008060 !important}" +
345→      W + " .zcc-cod--unavailable{color:#d72c0d !important}" +
346→      W + " .zcc-return-policy{margin-top:6px !important;font-size:0.85em !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:6px !important}" +
347→      W + " .zcc-wl-toggle{display:inline-flex !important;align-items:center !important;gap:6px !important;font-size:13px !important;font-weight:600 !important;color:" + cfg.primaryColor + " !important;text-decoration:none !important;cursor:pointer !important;border:none !important;background:none !important;padding:0 !important}" +
348→      W + " .zcc-wl-toggle:hover{text-decoration:underline !important}" +
349→      W + " .zcc-wl-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "20 !important}" +
