386→  // ── Style: Branded (two-tone header — colored band + white body) ──────────
387→  function buildBoldCss(wid, cfg, rad) {
388→    var W = "#" + wid;
389→    return (
390→      "@keyframes zcc-slide-in{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}" +
